SELECT COUNT(*) AS active_listings
FROM analytics.mart_listing_performance
WHERE is_active_last_12m = TRUE;

SELECT AVG(price) AS avg_nightly_price
FROM analytics.dim_listings
WHERE NOT is_price_outlier;

SELECT COUNT(*) AS total_listings
FROM analytics.dim_listings
WHERE 1 = 1
  AND {{room_type}}
  AND {{price_band}}
  AND {{minimum_nights_band}}
  AND {{is_superhost}}
  AND {{price}};

SELECT AVG(price) AS avg_nightly_price
FROM analytics.dim_listings
WHERE NOT is_price_outlier
  AND {{room_type}}
  AND {{price_band}}
  AND {{minimum_nights_band}}
  AND {{is_superhost}}
  AND {{price}};

SELECT COUNT(*) AS outlier_listings
FROM analytics.dim_listings
WHERE is_price_outlier = TRUE
  AND {{room_type}}
  AND {{price_band}}
  AND {{minimum_nights_band}}
  AND {{is_superhost}}
  AND {{price}};

SELECT COUNT(*) AS superhost_listings
FROM analytics.dim_listings
WHERE is_superhost = TRUE
  AND {{room_type}}
  AND {{price_band}}
  AND {{minimum_nights_band}}
  AND {{price}};

SELECT
    price_band,
    COUNT(*) AS listings
FROM analytics.dim_listings
WHERE 1 = 1
  AND {{room_type}}
  AND {{price_band}}
  AND {{minimum_nights_band}}
  AND {{is_superhost}}
  AND {{price}}
GROUP BY price_band
ORDER BY CASE price_band
    WHEN '<30' THEN 1
    WHEN '30-49' THEN 2
    WHEN '50-74' THEN 3
    WHEN '75-99' THEN 4
    WHEN '100-149' THEN 5
    WHEN '150-249' THEN 6
    ELSE 7
END;

SELECT
    minimum_nights_band,
    COUNT(*) AS listings
FROM analytics.dim_listings
WHERE 1 = 1
  AND {{room_type}}
  AND {{price_band}}
  AND {{minimum_nights_band}}
  AND {{is_superhost}}
  AND {{price}}
GROUP BY minimum_nights_band
ORDER BY CASE minimum_nights_band
    WHEN '1' THEN 1
    WHEN '2-6' THEN 2
    WHEN '7-29' THEN 3
    ELSE 4
END;

SELECT COUNT(*) AS total_reviews
FROM analytics.fct_reviews
WHERE 1 = 1
  AND {{review_date}}
  AND {{review_sentiment}}
  AND {{has_comment}};

SELECT AVG(sentiment_score) AS avg_sentiment_score
FROM analytics.fct_reviews
WHERE 1 = 1
  AND {{review_date}}
  AND {{review_sentiment}}
  AND {{has_comment}};

SELECT COUNT(*) AS reviews_2021
FROM analytics.fct_reviews
WHERE review_year = 2021
  AND {{review_date}}
  AND {{review_sentiment}}
  AND {{has_comment}};

SELECT
    review_month,
    COUNT(*) AS reviews
FROM analytics.fct_reviews
WHERE review_month <= DATE '2021-10-01'
  AND {{review_date}}
  AND {{review_sentiment}}
  AND {{has_comment}}
GROUP BY review_month
ORDER BY review_month;

SELECT
    review_sentiment,
    COUNT(*) AS reviews
FROM analytics.fct_reviews
WHERE 1 = 1
  AND {{review_date}}
  AND {{review_sentiment}}
  AND {{has_comment}}
GROUP BY review_sentiment
ORDER BY reviews DESC;

SELECT
    review_month,
    review_sentiment,
    COUNT(*) AS reviews
FROM analytics.fct_reviews
WHERE review_month <= DATE '2021-10-01'
  AND {{review_date}}
  AND {{review_sentiment}}
  AND {{has_comment}}
GROUP BY review_month, review_sentiment
ORDER BY review_month, review_sentiment;

SELECT
    dim_listings.room_type,
    COUNT(*) AS reviews
FROM analytics.fct_reviews
INNER JOIN analytics.dim_listings
    ON fct_reviews.listing_id = dim_listings.listing_id
WHERE 1 = 1
  AND {{review_date}}
  AND {{review_sentiment}}
  AND {{has_comment}}
  AND {{room_type}}
GROUP BY dim_listings.room_type
ORDER BY reviews DESC;

SELECT review_length
FROM analytics.fct_reviews
WHERE has_comment = TRUE
  AND {{review_date}}
  AND {{review_sentiment}}
  AND {{has_comment}};

SELECT
    topic,
    SUM(mentions) AS mentions
FROM analytics.mart_review_topics
WHERE 1 = 1
  AND {{review_month}}
  AND {{topic}}
GROUP BY topic
ORDER BY mentions DESC;

SELECT
    month_start,
    topic,
    AVG(mention_rate) AS avg_mention_rate
FROM analytics.mart_review_topics
WHERE month_start BETWEEN DATE '2019-11-01' AND DATE '2021-10-01'
  AND {{review_month}}
  AND {{topic}}
GROUP BY month_start, topic
ORDER BY month_start, topic;

SELECT
    topic,
    AVG(pct_negative) AS avg_pct_negative
FROM analytics.mart_review_topics
WHERE 1 = 1
  AND {{review_month}}
  AND {{topic}}
GROUP BY topic
ORDER BY avg_pct_negative DESC;

